from pathlib import Path
import re
mods=['PhaseContractions','LowAlphaConvolution','WaveGreenFourier','FockForm','ComplexPhaseScalar','RawOccupationEnergy','OccupationCeilingExact','GaussianHermite','HermiteFock','DampedMultiplier','WaveGreen']
extra={'PhaseContractions':[(139,154),(465,477),(745,751)],'LowAlphaConvolution':[(144,155)],'DampedMultiplier':[(236,246),(460,511),(547,590)],'WaveGreen':[(260,271),(427,452)]}
for mod in mods:
 p=Path('lean/StratonovichHAMSecondMoment/'+mod+'.lean');s=p.read_text().splitlines();v=set();active=None
 for i,l in enumerate(s,1):
  m=re.match(r'"'^(theorem|def|structure|variable|namespace|open |end |abbrev)'"',l)
  if m:active=m[1]
  if active:
   v.add(i)
   # first two modules used earlier extractor stopping definitions at assignment
   if (mod in ['PhaseContractions','LowAlphaConvolution'] and ':=' in l) or (mod not in ['PhaseContractions','LowAlphaConvolution'] and active=='theorem' and (':=' in l or l.endswith('where'))) or not l.strip() or re.match(r'"'^end '"',l):active=None
 for lo,hi in extra.get(mod,[]):v.update(range(lo,hi+1))
 a=sorted(v);ranges=[]
 for i in a:
  if ranges and ranges[-1][1]+1==i:ranges[-1][1]=i
  else:ranges.append([i,i])
 print(mod+': '+', '.join(str(x) if x==y else f'{x}-{y}' for x,y in ranges))
